#!/bin/sh
# Writes Sources/Dmbar/EmojiData.swift from GitHub's gemoji database, the
# source of the :shortcode: names (the ones GitHub and Slack use).
#   ./Support/make-emoji.sh            fetch gemoji's master and regenerate
#   ./Support/make-emoji.sh emoji.json regenerate from a local copy
set -eu
cd "$(dirname "$0")/.."

src="${1:-}"
if [ -z "$src" ]; then
  src=$(mktemp)
  trap 'rm -f "$src"' EXIT
  curl -sfL -o "$src" https://raw.githubusercontent.com/github/gemoji/master/db/emoji.json
fi

out=Sources/Dmbar/EmojiData.swift
{
  cat <<'EOF'
// Generated by Support/make-emoji.sh from github/gemoji's db/emoji.json
// (MIT, Copyright (c) 2019 GitHub, Inc.). Don't edit by hand.
//
// One emoji per line: emoji, category, shortcodes, then search words,
// separated by tabs; the lists inside are separated by spaces.

extension EmojiCatalog {
    nonisolated static let data = #"""
EOF
  jq -r '.[] | [.emoji, .category, (.aliases | join(" ")), ((.tags + [.description]) | join(" "))] | @tsv' "$src"
  cat <<'EOF'
"""#
}
EOF
} > "$out"
echo "wrote $out ($(grep -c '	' "$out") emoji)"
